#include "dsp/chain/AutoGain.h"

// Generated by tools/calibrate (UmberCalibrate). Re-run it whenever a model's sound changes.
#include "dsp/chain/AutoGainTables.h"

namespace umber::dsp
{

float AutoGain::compensationDb (Model model, float driveDb, float bias, float emphasis) noexcept
{
    const auto index = static_cast<size_t> (model);

    if (index < autoGainTables.size())
        return tableLookup (autoGainTables[index], driveDb, bias, emphasis);

    return estimateDb (driveDb);
}

} // namespace umber::dsp
